            int endParenIndex = descriptor.indexOf(')');
            if (endParenIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing closing parenthesis");
            }
            String argumentTypes = descriptor.substring(1, endParenIndex);
            parseAndPopArgumentTypes(argumentTypes);
        } else {
            popSingleType(descriptor);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
