private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }
    if (vertices.size() <= 1) {
        return true; // A single vertex or empty set is trivially a clique
    }
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("All vertices must be in the graph");
        }
    }
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!vertex1.equals(vertex2) && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

