                lb = lb.buffer(*lb.offset++) = (byte) (0x80 | (c & 0x3f));
            }
            if (lb.offset >= lb.limit) {
                lb = lb.next;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer", e);
    }
    return lb;
